module HintCounter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [7:0] m,\n    input wire [7:0] l_0, l_1, l_2, l_3,\n    input wire [7:0] r_0, r_1, r_2, r_3,\n    input wire type_0, type_1, type_2, type_3,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] COMPUTE = 2'b01;\n    localparam [1:0] DONE = 2'b10;\n\n    reg [1:0] state;\n    reg [7:0] seq;\n    reg [2:0] hint_idx;\n    reg [31:0] count;\n    reg [7:0] max_seq;\n\n    wire [7:0] current_l;\n    wire [7:0] current_r;\n    wire current_type;\n\n    assign current_l = (hint_idx == 0) ? l_0 :\n                      (hint_idx == 1) ? l_1 :\n                      (hint_idx == 2) ? l_2 : l_3;\n    assign current_r = (hint_idx == 0) ? r_0 :\n                      (hint_idx == 1) ? r_1 :\n                      (hint_idx == 2) ? r_2 : r_3;\n    assign current_type = (hint_idx == 0) ? type_0 :\n                         (hint_idx == 1) ? type_1 :\n                         (hint_idx == 2) ? type_2 : type_3;\n\n    wire [8:0] full_mask = (9'd1 << current_r) - (9'd1 << (current_l - 1));\n    wire [7:0] mask = full_mask[7:0] & ((1 << n) - 1);\n\n    wire [7:0] masked_bits = seq & mask;\n    wire bits_all_0 = (masked_bits == 8'b0);\n    wire bits_all_1 = (masked_bits == mask);\n\n    wire hint_pass = current_type ? ~(bits_all_0 | bits_all_1) : (bits_all_0 | bits_all_1);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            seq <= 8'd0;\n            hint_idx <= 3'd0;\n            count <= 32'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            max_seq <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= COMPUTE;\n                        seq <= 8'd0;\n                        hint_idx <= 3'd0;\n                        count <= 32'd0;\n                        done <= 1'b0;\n                        max_seq <= (1 << n) - 1;\n                    end\n                end\n                COMPUTE: begin\n                    if (seq > max_seq) begin\n                        state <= DONE;\n                        result <= count % 32'd1000000007;\n                        done <= 1'b1;\n                    end else if (hint_idx >= m) begin\n                        count <= count + 1'b1;\n                        seq <= seq + 1'b1;\n                        hint_idx <= 3'd0;\n                    end else if (hint_pass) begin\n                        hint_idx <= hint_idx + 1'b1;\n                    end else begin\n                        seq <= seq + 1'b1;\n                        hint_idx <= 3'd0;\n                    end\n                end\n                DONE: begin\n                    // Stay in DONE state\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule